-- Seed the Aurelius Health Systems policy document corpus into the
-- BigQuery vector index. Source of truth: knowledge/documents.json
-- (generated by scripts/build_document_corpus.py from documents/Markdown/).
-- Replace semantics: deletes documents no longer in the corpus, then
-- upserts all current documents. Idempotent. The table name
-- runbook_chunks is retained for deploy compatibility.

DELETE FROM `adk-dynatrace-observability.agent_observability.runbook_chunks`
WHERE doc_id NOT IN (
  "api-development-standards",
  "acceptable-use-policy",
  "access-control-policy",
  "anti-harassment-policy",
  "business-continuity-plan",
  "ci-cd-guidelines",
  "code-of-conduct",
  "compliance-governance-model",
  "data-flow-overview",
  "data-processing-overview",
  "data-retention-policy",
  "disaster-recovery-runbook",
  "employee-handbook",
  "employee-nda",
  "enterprise-risk-register",
  "escalation-matrix",
  "information-security-policy",
  "internal-audit-process",
  "internal-ip-policy",
  "leave-and-attendance-policy",
  "logging-standards",
  "logging-and-monitoring-policy",
  "metrics-and-reporting-framework",
  "operational-kpis",
  "password-and-mfa-policy",
  "performance-review-process",
  "policy-exception-process",
  "raci-matrix",
  "records-management-statement",
  "remote-work-policy",
  "risk-assessment-methodology",
  "sop-backup-and-recovery",
  "sop-change-management",
  "sop-data-access-approval",
  "sop-employee-offboarding",
  "sop-employee-onboarding",
  "sop-it-incident-response",
  "sop-release-management",
  "sop-vendor-onboarding",
  "security-awareness-training",
  "system-architecture-overview",
  "third-party-risk-management",
  "threat-modeling-overview",
  "vendor-confidentiality-terms",
  "vulnerability-management-process",
  "workplace-safety-policy"
);

CREATE TEMP TABLE generated_documents AS
SELECT *
FROM AI.GENERATE_EMBEDDING(
  MODEL `adk-dynatrace-observability.agent_observability.embedding_model`,
  (
    SELECT
      "api-development-standards" AS doc_id,
      "API Development Standards" AS title,
      "# API Development Standards

**Company:** Aurelius Health Systems  
**Document Type:** ENGINEERING  
**Department:** Engineering  
**Version:** 1.0  
**Classification:** Internal  

## Purpose
This document defines internal standards, procedures, and expectations for Aurelius Health Systems.
It is intended to support consistent operations, regulatory readiness, and secure handling of data.

## Scope
This document applies to all employees, contractors, and systems operated or managed by Aurelius Health Systems.

## Roles & Responsibilities
- Leadership ensures enforcement and governance.
- Department owners maintain and review this document annually.
- Employees are responsible for compliance.

## Policy / Procedure Details
Aurelius Health Systems follows industry best practices to ensure operational excellence.
Controls, approvals, and documentation are required where applicable.
Deviations must be documented and approved by management.

## Enforcement
Violations may result in disciplinary action up to and including termination.

## Review & Maintenance
This document is reviewed at least annually or upon significant organizational or regulatory change." AS content,
      "engineering" AS category,
      "documents/Markdown/API_Development_Standards.md" AS source,
      ["sre"] AS allowed_roles
    UNION ALL
    SELECT
      "acceptable-use-policy" AS doc_id,
      "Acceptable Use Policy" AS title,
      "# Acceptable Use Policy

**Company:** Aurelius Health Systems  
**Document Type:** POLICIES  
**Department:** Policies  
**Version:** 1.0  
**Classification:** Internal  

## Purpose
